// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAccounts The user's accounts
	// (GET /accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request)
	// CreateAccount Create an account
	// (POST /accounts)
	CreateAccount(w http.ResponseWriter, r *http.Request)
	// DeleteAccount Delete an account with its imports and transactions
	// (DELETE /accounts/{id})
	DeleteAccount(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateAccount Change an account
	// (PATCH /accounts/{id})
	UpdateAccount(w http.ResponseWriter, r *http.Request, id Id)
	// ListAssistantChats The user's chats, newest first
	// (GET /assistant/chats)
	ListAssistantChats(w http.ResponseWriter, r *http.Request)
	// CreateAssistantChat Start a chat
	// (POST /assistant/chats)
	CreateAssistantChat(w http.ResponseWriter, r *http.Request)
	// DeleteAssistantChat Delete a chat
	// (DELETE /assistant/chats/{id})
	DeleteAssistantChat(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// GetAssistantChat A chat with its turns
	// (GET /assistant/chats/{id})
	GetAssistantChat(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// SendAssistantMessage Ask a question; the answer streams back
	// (POST /assistant/chats/{id}/messages)
	SendAssistantMessage(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// StopAssistant Stop the reply being written
	// (POST /assistant/chats/{id}/stop)
	StopAssistant(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// GetAssistantSettings The user's assistant settings
	// (GET /assistant/settings)
	GetAssistantSettings(w http.ResponseWriter, r *http.Request)
	// PutAssistantSettings Save the assistant settings
	// (PUT /assistant/settings)
	PutAssistantSettings(w http.ResponseWriter, r *http.Request)
	// AssistantStatus The assistant's connections and their models
	// (GET /assistant/status)
	AssistantStatus(w http.ResponseWriter, r *http.Request, params AssistantStatusParams)
	// Login Sign in
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Sign out
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Signup Create an account and sign in
	// (POST /auth/signup)
	Signup(w http.ResponseWriter, r *http.Request)
	// ListBudgets The budgets set by hand
	// (GET /budgets)
	ListBudgets(w http.ResponseWriter, r *http.Request)
	// PutBudget Set or reset a category's budget
	// (PUT /budgets/{categoryId})
	PutBudget(w http.ResponseWriter, r *http.Request, categoryId openapi_types.UUID)
	// ListCategories Categories with counts and colour slots
	// (GET /categories)
	ListCategories(w http.ResponseWriter, r *http.Request, params ListCategoriesParams)
	// CreateCategory Create a category
	// (POST /categories)
	CreateCategory(w http.ResponseWriter, r *http.Request)
	// CategoryStats Every category with its counts (Settings → Categories)
	// (GET /categories/stats)
	CategoryStats(w http.ResponseWriter, r *http.Request)
	// DeleteCategory Delete a category (its transactions become uncategorised)
	// (DELETE /categories/{id})
	DeleteCategory(w http.ResponseWriter, r *http.Request, id Id)
	// RenameCategory Rename a category
	// (PATCH /categories/{id})
	RenameCategory(w http.ResponseWriter, r *http.Request, id Id)
	// MergeCategory Merge a category into another one and delete it
	// (POST /categories/{id}/merge)
	MergeCategory(w http.ResponseWriter, r *http.Request, id Id)
	// LoadDemoData Create a demo account with the generated demo year
	// (POST /demo-data)
	LoadDemoData(w http.ResponseWriter, r *http.Request)
	// ListDuplicates Duplicate groups with every version (the duplicates window)
	// (GET /duplicates)
	ListDuplicates(w http.ResponseWriter, r *http.Request, params ListDuplicatesParams)
	// ResetDuplicate Back to the default merge ("Merge again")
	// (DELETE /duplicates/{accountId}/{fingerprint})
	ResetDuplicate(w http.ResponseWriter, r *http.Request, accountId openapi_types.UUID, fingerprint string)
	// DecideDuplicate Use one version, or keep both
	// (PUT /duplicates/{accountId}/{fingerprint})
	DecideDuplicate(w http.ResponseWriter, r *http.Request, accountId openapi_types.UUID, fingerprint string)
	// ListGroups Groups with their stats
	// (GET /groups)
	ListGroups(w http.ResponseWriter, r *http.Request)
	// CreateGroup Create a group
	// (POST /groups)
	CreateGroup(w http.ResponseWriter, r *http.Request)
	// DeleteGroup Delete a group (its labels only, never transactions)
	// (DELETE /groups/{id})
	DeleteGroup(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateGroup Rename, recolour or budget a group
	// (PATCH /groups/{id})
	UpdateGroup(w http.ResponseWriter, r *http.Request, id Id)
	// GroupReport A group's report (the group window)
	// (GET /groups/{id}/report)
	GroupReport(w http.ResponseWriter, r *http.Request, id Id)
	// ListImports Imports, newest first
	// (GET /imports)
	ListImports(w http.ResponseWriter, r *http.Request, params ListImportsParams)
	// UploadImport Upload a bank export and get a preview
	// (POST /imports)
	UploadImport(w http.ResponseWriter, r *http.Request, params UploadImportParams)
	// DeleteImport Delete an import (cancel a preview, or remove a committed import)
	// (DELETE /imports/{id})
	DeleteImport(w http.ResponseWriter, r *http.Request, id Id)
	// GetImport One import
	// (GET /imports/{id})
	GetImport(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateImport Change the account, mapping or options of a previewed import
	// (PATCH /imports/{id})
	UpdateImport(w http.ResponseWriter, r *http.Request, id Id)
	// CommitImport Commit a previewed import
	// (POST /imports/{id}/commit)
	CommitImport(w http.ResponseWriter, r *http.Request, id Id)
	// GetImportFile The original file
	// (GET /imports/{id}/file)
	GetImportFile(w http.ResponseWriter, r *http.Request, id Id)
	// ListImportLines Decoded records of the file with their status (header-row picker)
	// (GET /imports/{id}/lines)
	ListImportLines(w http.ResponseWriter, r *http.Request, id Id, params ListImportLinesParams)
	// ReprocessImport Re-read a committed import with a new mapping or options
	// (POST /imports/{id}/reprocess)
	ReprocessImport(w http.ResponseWriter, r *http.Request, id Id)
	// ListImportRows Staged rows of an import
	// (GET /imports/{id}/rows)
	ListImportRows(w http.ResponseWriter, r *http.Request, id Id, params ListImportRowsParams)
	// InsightCashflow Money in and out per month
	// (POST /insights/cashflow)
	InsightCashflow(w http.ResponseWriter, r *http.Request)
	// InsightCategories Spending by category, largest first
	// (POST /insights/categories)
	InsightCategories(w http.ResponseWriter, r *http.Request)
	// InsightDaily Spending per day for the calendar
	// (POST /insights/daily)
	InsightDaily(w http.ResponseWriter, r *http.Request)
	// InsightPace Cumulative spending through a month vs a comparison
	// (POST /insights/pace)
	InsightPace(w http.ResponseWriter, r *http.Request)
	// InsightPayees Top payees by spending
	// (POST /insights/payees)
	InsightPayees(w http.ResponseWriter, r *http.Request)
	// InsightSummary Summary card (spent, income, net, average per day, largest expense)
	// (POST /insights/summary)
	InsightSummary(w http.ResponseWriter, r *http.Request)
	// GetInvestments The manual investment data
	// (GET /investments)
	GetInvestments(w http.ResponseWriter, r *http.Request)
	// PutInvestments Replace the investment data
	// (PUT /investments)
	PutInvestments(w http.ResponseWriter, r *http.Request)
	// ListLegacyImports The user's latest migrations from the single-file app, newest first
	// (GET /legacy-imports)
	ListLegacyImports(w http.ResponseWriter, r *http.Request)
	// CreateLegacyImport Migrate a backup of the single-file app
	// (POST /legacy-imports)
	CreateLegacyImport(w http.ResponseWriter, r *http.Request)
	// GetLegacyImport A migration's progress and report
	// (GET /legacy-imports/{id})
	GetLegacyImport(w http.ResponseWriter, r *http.Request, id Id)
	// DeleteMe Delete the account and all of its data
	// (DELETE /me)
	DeleteMe(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in user
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Change the display name
	// (PATCH /me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// ListActivity The user's activity log (Settings → Activity)
	// (GET /me/activity)
	ListActivity(w http.ResponseWriter, r *http.Request, params ListActivityParams)
	// ExportMe Download all of the user's data
	// (GET /me/export)
	ExportMe(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change the password
	// (POST /me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// ListSessions The user's active sessions
	// (GET /me/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// RevokeSession Sign out one session
	// (DELETE /me/sessions/{id})
	RevokeSession(w http.ResponseWriter, r *http.Request, id string)
	// GetMeta Public instance information
	// (GET /meta)
	GetMeta(w http.ResponseWriter, r *http.Request)
	// Overview Everything the overview page shows for one month
	// (POST /overview)
	Overview(w http.ResponseWriter, r *http.Request)
	// GetPreferences The user's UI preferences
	// (GET /preferences)
	GetPreferences(w http.ResponseWriter, r *http.Request)
	// PutPreferences Replace the UI preferences
	// (PUT /preferences)
	PutPreferences(w http.ResponseWriter, r *http.Request)
	// ListRules The rules in the order they apply
	// (GET /rules)
	ListRules(w http.ResponseWriter, r *http.Request)
	// CreateRule Create a rule (it goes last)
	// (POST /rules)
	CreateRule(w http.ResponseWriter, r *http.Request, params CreateRuleParams)
	// ApplyRules Re-apply every rule and look for transfers again
	// (POST /rules/apply)
	ApplyRules(w http.ResponseWriter, r *http.Request)
	// ReorderRules Set the order the rules apply in
	// (PUT /rules/order)
	ReorderRules(w http.ResponseWriter, r *http.Request)
	// PreviewRule What a match selects now
	// (POST /rules/preview)
	PreviewRule(w http.ResponseWriter, r *http.Request)
	// RuleSuggestions Rules worth creating (the toolbar card)
	// (GET /rules/suggestions)
	RuleSuggestions(w http.ResponseWriter, r *http.Request)
	// DeleteRule Delete a rule
	// (DELETE /rules/{id})
	DeleteRule(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateRule Replace a rule (its position stays)
	// (PUT /rules/{id})
	UpdateRule(w http.ResponseWriter, r *http.Request, id Id)
	// BulkUpdateTransactions Change the group, category or transfer state of many transactions
	// (POST /transactions/bulk)
	BulkUpdateTransactions(w http.ResponseWriter, r *http.Request, params BulkUpdateTransactionsParams)
	// DistinctValues A column's values with counts (the value checklist)
	// (POST /transactions/distinct)
	DistinctValues(w http.ResponseWriter, r *http.Request)
	// ExportTransactions The filtered, sorted rows as CSV
	// (POST /transactions/export)
	ExportTransactions(w http.ResponseWriter, r *http.Request)
	// TransactionRange Ids and amounts of a range of the ordered result (range selection)
	// (POST /transactions/ids)
	TransactionRange(w http.ResponseWriter, r *http.Request)
	// QueryTransactions A window of transactions with totals
	// (POST /transactions/query)
	QueryTransactions(w http.ResponseWriter, r *http.Request)
	// GetTransaction One transaction with its raw fields and source imports
	// (GET /transactions/{id})
	GetTransaction(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateTransaction Set the category or the note
	// (PATCH /transactions/{id})
	UpdateTransaction(w http.ResponseWriter, r *http.Request, id Id)
}

